--
-- Name: ventas; Type: TABLE; Schema: operaciones; Owner: postgres
--

CREATE TABLE operaciones.ventas (
    id_venta integer NOT NULL,
    id_usuario integer NOT NULL,
    id_tienda integer NOT NULL,
    fecha_venta timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    subtotal integer NOT NULL,
    total_iva integer DEFAULT 0 NOT NULL,
    total integer NOT NULL,
    estado character varying(20) DEFAULT 'completada'::character varying NOT NULL,
    metodo_pago character varying(50) DEFAULT 'efectivo'::character varying NOT NULL
);


ALTER TABLE operaciones.ventas OWNER TO postgres;

--
-- Name: ventas_diarias_mv; Type: MATERIALIZED VIEW; Schema: operaciones; Owner: postgres
--

CREATE MATERIALIZED VIEW operaciones.ventas_diarias_mv AS
 SELECT id_producto,
    id_tienda,
    date(fecha_movimiento) AS fecha,
    sum(abs(cantidad)) AS demanda_diaria
   FROM inventario.movimientos_stock m
  WHERE ((tipo_movimiento)::text = 'VENTA'::text)
  GROUP BY id_producto, id_tienda, (date(fecha_movimiento))
  WITH NO DATA;


ALTER MATERIALIZED VIEW operaciones.ventas_diarias_mv OWNER TO postgres;

